      ],
      "reason": "Căn bếp thường có ánh sáng tự nhiên từ cửa sổ, nhưng cũng có thể có ánh sáng nhân tạo từ đèn.",
      "suggestion": "Sử dụng ánh sáng tự nhiên từ cửa sổ bên trái, tạo ra một góc khuất ở bên phải, làm nổi bật thư trên bàn.",
      "purpose": "Tạo sự tập trung vào thư và tạo cảm giác bí ẩn."
    },
    {
      "field": "costume",
      "evidence": [
        {
          "source_id": "scene:5a07d1e0-a2b4-41c9-90f1-2f6b81932ee4:characters",
          "quote": "Cha, con gái"
        }
      ],
      "reason": "Cha và con gái mặc quần áo hàng ngày, không có gì đặc biệt.",
      "suggestion": "Cha mặc áo sơ mi trắng và quần jean, con gái mặc áo phông và quần jean, cả hai đều mang giày thể thao.",
      "purpose": "Tạo cảm giác tự nhiên và không gây chú ý."
    },
    {
      "field": "composition",
      "evidence": [
        {
          "source_id": "scene:5a07d1e0-a2b4-41c9-90f1-2f6b81932ee4:action",
          "quote": "Cha đặt thư lên bàn, rút tay. Con gái dừng bên ghế, nhìn cha rồi nhìn lá thư; cắt khi cô chưa chạm vào thư."
        }
      ],
      "reason": "Cha và con gái đều nhìn vào thư, tạo ra một hình ảnh đối lập.",
      "suggestion": "Thư nằm giữa cha và con gái, tạo ra một hình ảnh đối lập giữa hai người.",
      "purpose": "Tạo cảm giác đối lập và giữ cho không khí căng thẳng."
    },
    {
      "field": "angle",
      "evidence": [
        {
          "source_id": "scene:5a07d1e0-a2b4-41c9-90f1-2f6b81932ee4:action",
          "quote": "Cha đặt thư lên bàn, rút tay. Con gái dừng bên ghế, nhìn cha rồi nhìn lá thư; cắt khi cô chưa chạm vào thư."
        }
      ],
      "reason": "Cha và con gái đều nhìn vào thư, tạo ra một hình ảnh đối lập.",
      "suggestion": "Sử dụng góc nhìn từ trên xuống, tạo ra một cảm giác quan sát từ bên ngoài.",
      "purpose": "Tạo cảm giác quan sát từ bên ngoài và giữ cho không khí căng thẳng."
    }
  ]
}

